import{_ as t,o as s,c as e,a2 as o}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"CachyOS","description":"","frontmatter":{},"headers":[],"relativePath":"installation/cachyos.md","filePath":"installation/cachyos.md","lastUpdated":1792044498000}'),r={name:"installation/cachyos.md"};function i(c,a,l,h,n,p){return s(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="cachyos" tabindex="-1">CachyOS <a class="header-anchor" href="#cachyos" aria-label="Permalink to &quot;CachyOS&quot;">​</a></h1><p><strong>官网</strong>：<a href="https://cachyos.org" target="_blank" rel="noreferrer">https://cachyos.org</a></p><p><strong>当前版本</strong>：滚动发布（基于 Arch Linux）</p><p>基于 Arch 的滚动发行版，主打高性能：默认使用优化过的内核（Cachy 内核）、x86-64-v3/v4 编译优化，安装简单、驱动自动配置。适合想要 Arch 但不想手动折腾安装的用户。</p><ul><li>下载：<a href="https://cachyos.org/download" target="_blank" rel="noreferrer">https://cachyos.org/download</a></li><li>特点：BORE/Cachy 内核、游戏优化、图形化安装器、自带 Shelly 包管理器</li></ul><h2 id="安装后-关闭默认防火墙" tabindex="-1">安装后：关闭默认防火墙 <a class="header-anchor" href="#安装后-关闭默认防火墙" aria-label="Permalink to &quot;安装后：关闭默认防火墙&quot;">​</a></h2><p>无论终端安装还是图形化安装，系统默认都启用了 UFW 防火墙，需要手动关闭：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ufw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span></code></pre></div><blockquote><p>装完记得用 <code>sudo ufw status</code> 确认状态。</p></blockquote>',9)])])}const _=t(r,[["render",i]]);export{u as __pageData,_ as default};
